-- public.hire_onboarding_templates: 14 rows
insert into public.hire_onboarding_templates ("key", "label", "description", "phase", "kind", "owner_role", "due_day", "window_from_day", "employment", "sort", "is_active", "updated_at")
select "key", "label", "description", "phase", "kind", "owner_role", "due_day", "window_from_day", "employment", "sort", "is_active", "updated_at" from json_populate_recordset(null::public.hire_onboarding_templates, $ref$[{"key": "day1_welcome", "label": "Day 1: welcome, mission, values, positioning", "description": "Welcome call with the manager, team intro at the daily huddle, the company mission / values / positioning, the 1:1 cadence set (3-5 targeted interactions a week in the first 30 days).", "phase": 1, "kind": "meeting", "owner_role": "manager", "due_day": 1, "window_from_day": null, "employment": ["full_time", "part_time", "contractor", "intern"], "sort": 10, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}, {"key": "week1_tools", "label": "Week 1: tools, channels, Drive, training videos", "description": "Workflow and tools orientation: Slack, Google Workspace, Airtable / Open Ronin, GHL where relevant, the Shared Drive, the training video library. The hire reviews the videos and lists open questions in the daily check-in.", "phase": 1, "kind": "task", "owner_role": "hire", "due_day": 5, "window_from_day": 1, "employment": ["full_time", "part_time", "contractor", "intern"], "sort": 20, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}, {"key": "week2_clients", "label": "Week 2: client portfolio overview + shadowing", "description": "Client portfolio walkthrough; shadow internal and client meetings (delivery calls, Friday recaps).", "phase": 1, "kind": "task", "owner_role": "manager", "due_day": 12, "window_from_day": 6, "employment": ["full_time", "part_time", "contractor", "intern"], "sort": 30, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}, {"key": "week3_first_work", "label": "Week 3: first owned deliverables", "description": "First real deliverables with review (media opps, recaps, lists, code — whatever the role does). Informal feedback loop every day.", "phase": 1, "kind": "task", "owner_role": "hire", "due_day": 19, "window_from_day": 13, "employment": ["full_time", "part_time", "contractor", "intern"], "sort": 40, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}, {"key": "week4_independent", "label": "Week 4: working more independently", "description": "The hire runs their daily work with lighter review; manager notes friction points for the day-30 conversation.", "phase": 1, "kind": "task", "owner_role": "manager", "due_day": 26, "window_from_day": 20, "employment": ["full_time", "part_time", "contractor", "intern"], "sort": 50, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}, {"key": "day30_reflection", "label": "Day 30: Mini Reflection Conversation", "description": "Lightweight prompts: What feels clear about your role? What feels unclear? Where do you feel confident? Where do you need more support? What has surprised you? Record the answers on this item.", "phase": 1, "kind": "milestone", "owner_role": "manager", "due_day": 30, "window_from_day": 28, "employment": ["full_time", "part_time", "contractor", "intern"], "sort": 60, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}, {"key": "role_definition", "label": "Module 1: Role definition", "description": "Define core responsibilities, measurable outcomes, role boundaries and success indicators against the 4R. Deliverable: role clarity summary validated by the manager (the profile 4R).", "phase": 2, "kind": "module", "owner_role": "manager", "due_day": 40, "window_from_day": 31, "employment": ["full_time", "part_time", "contractor"], "sort": 70, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}, {"key": "pap_v1", "label": "Module 2: Personal Action Plan (PAP v1)", "description": "Top 5 recurring responsibilities, 30-60-90 action plan, measurable success indicators; reviewed and validated by the manager. Deliverable: approved PAP on the profile.", "phase": 2, "kind": "module", "owner_role": "manager", "due_day": 50, "window_from_day": 40, "employment": ["full_time", "part_time", "contractor"], "sort": 80, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}, {"key": "disc", "label": "Module 3: DISC assessment", "description": "Between days 45-60, once there is relational context: complete the in-app DISC-style questionnaire (or enter existing results), identify primary / secondary traits, write the \"How I Work Best\" summary, share with the manager.", "phase": 2, "kind": "module", "owner_role": "hire", "due_day": 55, "window_from_day": 45, "employment": ["full_time", "part_time", "contractor", "intern"], "sort": 90, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}, {"key": "how_i_work_best", "label": "\"How I Work Best\" one-pager", "description": "The DISC one-pager documented on the profile and shared with the manager (team share optional).", "phase": 2, "kind": "task", "owner_role": "hire", "due_day": 60, "window_from_day": 55, "employment": ["full_time", "part_time", "contractor", "intern"], "sort": 100, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}, {"key": "day60_review", "label": "Day 60: onboarding review (60-Day Plan complete)", "description": "Close the 60-Day Plan: review the targeted-interaction packet, confirm Phase 2 deliverables, agree the Phase 3 dates. From here the person joins the next calibration cycle.", "phase": 2, "kind": "milestone", "owner_role": "manager", "due_day": 60, "window_from_day": 58, "employment": ["full_time", "part_time", "contractor", "intern"], "sort": 110, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}, {"key": "ppf", "label": "Module 4: Personal Priorities Framework (PPF)", "description": "Complete the PPF: top 3 strategic priorities, development trajectory, misalignments or risks flagged. Deliverable: approved PPF documented.", "phase": 3, "kind": "module", "owner_role": "manager", "due_day": 75, "window_from_day": 61, "employment": ["full_time", "part_time", "contractor"], "sort": 120, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}, {"key": "time_study", "label": "Module 5: Time Study (5 consecutive working days)", "description": "Between days 75-90: track time for 5 consecutive working days with the predefined categories (Tools → Time Study), calculate the distribution, reflect on capacity, review with the manager.", "phase": 3, "kind": "module", "owner_role": "hire", "due_day": 85, "window_from_day": 75, "employment": ["full_time", "part_time", "contractor"], "sort": 130, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}, {"key": "day90_review", "label": "Day 90: review & completion", "description": "Review PAP, PPF and the Time Study; structured feedback conversation; confirm role calibration. Onboarding marked complete.", "phase": 3, "kind": "milestone", "owner_role": "manager", "due_day": 90, "window_from_day": 88, "employment": ["full_time", "part_time", "contractor", "intern"], "sort": 140, "is_active": true, "updated_at": "2026-10-02T12:45:00.662596+00:00"}]$ref$::json)
on conflict do nothing;

-- public.calibration_questions: 15 rows
insert into public.calibration_questions ("id", "tenant_id", "key", "group_key", "label", "prompt", "weight", "position", "rubric", "is_active", "created_at", "updated_at")
select "id", "tenant_id", "key", "group_key", "label", "prompt", "weight", "position", "rubric", "is_active", "created_at", "updated_at" from json_populate_recordset(null::public.calibration_questions, $ref$[{"id": "f83979cf-f089-4804-a2a0-d101bdce3296", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "transparency", "group_key": "core", "label": "Transparency", "prompt": "Rate TRANSPARENCY", "weight": 5, "position": 1, "rubric": ["Conceals information or misrepresents the truth.", "Hides problems or shares information only when asked.", "Shares updates, but often late or incomplete.", "Shares status and problems openly as they come up.", "Surfaces problems, numbers, and mistakes early without being asked.", "Fully open book; raises hard truths early and makes it safe for others to do the same."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "d2af0f8d-2673-45ca-864f-484acfe026db", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "obsessed", "group_key": "core", "label": "Obsessed", "prompt": "Rate OBSESSED", "weight": 5, "position": 2, "rubric": ["Disengaged; does not care about the work or the mission.", "Treats the work as just a job; does the minimum.", "Cares about the work in bursts; attention fades.", "Consistently cares about quality and client outcomes.", "Goes beyond the role to get things right; thinks ahead without prompting.", "Relentless about the mission and the standard; their energy raises the team."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "57c2a03e-4188-40f7-b43a-16923401e433", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "leadership", "group_key": "core", "label": "Leadership (includes Ownership)", "prompt": "Rate LEADERSHIP, including ownership", "weight": 5, "position": 3, "rubric": ["Undermines leadership or the team; refuses responsibility.", "Waits for direction; makes excuses or shifts blame.", "Leads their own tasks; owns problems once confronted.", "Leads by example; owns results and mistakes and fixes what they break.", "Develops others, takes charge in hard moments, and solves problems beyond their role unprompted.", "A trusted leader others follow; treats the company's problems as their own and multiplies the team's output."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "7b8efde9-b991-4da0-a663-4e985f2563fc", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "growth", "group_key": "core", "label": "Growth", "prompt": "Rate GROWTH", "weight": 5, "position": 4, "rubric": ["Regressed or refused to develop.", "No visible personal or professional growth this quarter.", "Some growth, mostly when pushed.", "Steady growth; applies feedback and new learning.", "Clear growth; noticeably more capable than last quarter.", "Exceptional growth; ready for more responsibility now."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "fdea5cc4-065e-4e96-b9f5-61f8ae4f7c87", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "intentionality", "group_key": "core", "label": "Intentionality", "prompt": "Rate INTENTIONALITY", "weight": 5, "position": 5, "rubric": ["No planning; ignores priorities and the 12 Week plan.", "Reactive; works on whatever is in front of them.", "Plans sometimes, but priorities drift.", "Plans the week and works mostly on priorities.", "Protects time for high value work; every week ties to goals.", "Every action ties to the 12 Week plan; time, focus, and words are deliberate."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "05f1f817-3b83-443c-adc2-52f0caf2f8cb", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "execution", "group_key": "core", "label": "Execution (includes Results)", "prompt": "Rate EXECUTION, including results", "weight": 5, "position": 6, "rubric": ["Did not deliver; commitments abandoned.", "Commitments regularly missed; few results.", "Gets some things done; results are inconsistent.", "Completes work consistently and delivers expected results.", "Executes at a high level and delivers above expected results.", "Executes flawlessly; results exceed goals and lift the department."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "eee8c309-7411-4730-a857-2dcb554ceee7", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "teamwork", "group_key": "core", "label": "Teamwork", "prompt": "Rate TEAMWORK", "weight": 5, "position": 7, "rubric": ["Damages team trust or unity.", "Works in a silo or creates friction.", "Cooperates when asked.", "Reliable teammate; helps and shares the load.", "Actively makes teammates better; first to help.", "The glue of the team; builds unity across pods and departments."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "d213a719-89d2-4a38-a261-336eb424c7ca", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "metrics", "group_key": "performance", "label": "Metrics", "prompt": "Rate METRICS", "weight": 10, "position": 8, "rubric": ["Numbers missing, ignored, or misreported.", "Does not know or track their numbers.", "Knows their numbers but misses most targets.", "Tracks numbers weekly and hits most targets.", "Hits every target and uses data to improve.", "Exceeds every target and drives the numbers that matter most to the department."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "98e7a446-86ab-4d3c-a50f-3780cb05c60e", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "impact", "group_key": "performance", "label": "Impact (client or org, includes Contribution)", "prompt": "Rate IMPACT on clients or the company, including contribution", "weight": 10, "position": 9, "rubric": ["Net negative; their work created more problems than value.", "Little measurable contribution to clients or the company.", "Some contribution, mostly limited to assigned tasks.", "Solid contribution; clients and the team clearly benefit.", "High impact; clear wins for clients or the company; a top contributor in the pod.", "The top contributor in the department; moved client results or the company forward in ways people can point to."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "4677c11b-7bdc-4d82-b1d2-12be5f4f3185", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "initiative", "group_key": "performance", "label": "Initiative+Innovation (includes New Skills)", "prompt": "Rate INITIATIVE+INNOVATION, including new skills", "weight": 10, "position": 10, "rubric": ["Resists change and new ideas.", "Does only what is assigned; learned no new skills.", "Occasional ideas with little follow through; minimal new skills.", "Brings ideas, acts on some, and learned at least one new skill.", "Regularly improves processes and applies new skills to the work.", "Creates solutions, tools, or offers the company adopts; teaches new skills to others."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "8b3ff60a-45f3-481a-aaa9-054b432c6281", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "projects", "group_key": "performance", "label": "Projects+Systems", "prompt": "Rate PROJECTS+SYSTEMS", "weight": 10, "position": 11, "rubric": ["No projects delivered; nothing documented.", "Projects stalled or abandoned; work lives only in their head.", "Projects behind or below standard; little documented.", "Projects completed to standard; key processes documented.", "Projects completed well with minimal oversight; SOPs built or improved so others can repeat the work.", "Projects completed with excellence; the systems they built become the model for the department."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "07245003-5d08-44f9-b0ac-4222a60649d8", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "timelines", "group_key": "performance", "label": "Timelines", "prompt": "Rate TIMELINES", "weight": 5, "position": 12, "rubric": ["Deadlines ignored entirely.", "Regularly misses deadlines without warning.", "Misses some deadlines; flags them late.", "Meets most deadlines and flags risk early.", "Meets every deadline.", "Consistently delivers early and helps others hit theirs."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "bcd568ce-586e-4c91-8c14-eb5336710d75", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "four_r", "group_key": "professional", "label": "4R Fulfillment", "prompt": "Rate 4R FULFILLMENT", "weight": 10, "position": 13, "rubric": ["4R ignored entirely.", "4R expectations not met.", "Some 4R expectations met, inconsistently.", "4R expectations met consistently.", "4R fully met with strong quality.", "4R exceeded and modeled for others."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "a779d64c-2d7b-4e82-b88b-ae014895434a", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "communication", "group_key": "professional", "label": "Communication", "prompt": "Rate COMMUNICATION", "weight": 5, "position": 14, "rubric": ["Unreachable or misleading.", "Hard to reach; updates unclear or missing.", "Responsive, but updates are unclear or inconsistent.", "Clear, timely communication with team and clients.", "Proactive and concise; keeps everyone informed without being asked.", "Builds trust through communication; no one ever wonders where things stand."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}, {"id": "7702c68a-2591-4076-8609-efa44d01ece4", "tenant_id": "a7f0f5c2-0000-4000-8000-000000000001", "key": "book", "group_key": "professional", "label": "Book Completion", "prompt": "Rate BOOK COMPLETION", "weight": 5, "position": 15, "rubric": ["Did not start the assigned reading.", "Finished less than half the assigned reading.", "Finished most, but not all, of the assigned reading.", "Finished the assigned reading.", "Finished and applied the lessons to their work.", "Finished, applied, and taught the lessons to the team."], "is_active": true, "created_at": "2026-10-02T03:59:47.342724+00:00", "updated_at": "2026-10-02T03:59:47.342724+00:00"}]$ref$::json)
on conflict do nothing;

